import { test, expect } from '@playwright/test';

test.describe('Logout from Side Menu', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should successfully log out a signed-in user from the side menu', async ({ page }) => {
    // Login with standard user credentials
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: 'Login' });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Verify user is logged in
    const inventoryItem = page.getByText('inventory');
    await expect(inventoryItem).toBeVisible();

    // Open the side menu using the burger menu button
    const burgerMenuButton = page.getByRole('button', { name: /burger menu/i });
    await burgerMenuButton.click();

    // Verify side menu is open
    const sideMenu = page.locator('[data-testid="side-menu"]');
    await expect(sideMenu).toBeVisible();

    // Click the logout link
    const logoutLink = page.getByRole('link', { name: /logout/i });
    await logoutLink.click();

    // Verify user is redirected to login page
    await expect(page).toHaveURL('https://www.saucedemo.com/');
    await expect(inventoryItem).not.toBeVisible();

    // Verify login button is visible again
    await expect(loginButton).toBeVisible();
  });

  test('should handle logout when side menu is not open', async ({ page }) => {
    // Login with standard user credentials
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: 'Login' });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Verify user is logged in
    const inventoryItem = page.getByText('inventory');
    await expect(inventoryItem).toBeVisible();

    // Click the logout link directly (should not open menu first)
    const logoutLink = page.getByRole('link', { name: /logout/i });
    await logoutLink.click();

    // Verify user is redirected to login page
    await expect(page).toHaveURL('https://www.saucedemo.com/');
    await expect(inventoryItem).not.toBeVisible();

    // Verify login button is visible again
    await expect(loginButton).toBeVisible();
  });
});
